content.css:
.hjv-root {
  width: 100%;
  height: 100%;
  overflow: auto;
  position: relative;
}
.hjv-conteudo {
  width: 100%;
  min-height: 100%;
}
.hjv-vazio {
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 12px;
  color: #6b7280;
  padding: 16px;
}
.hjv-erro {
  position: absolute;
  left: 8px;
  right: 8px;
  bottom: 8px;
  font-family: Consolas, monospace;
  font-size: 11px;
  color: #991b1b;
  background: #fee2e2;
  border: 1px solid #fca5a5;
  border-radius: 4px;
  padding: 6px 8px;
  z-index: 1000;
}
